/**
 * Card component for displaying music tracks or albums
 *
 * @example
 * // Basic usage
 * <Card item={track} />
 *
 * @example
 * // With platform-specific styling
 * <Card
 *   item={track}
 *   platform="spotify"
 *   theme="dark"
 *   hoverEffect="lift"
 *   showPlayButton
 *   onPlay={() => playTrack(track.id)}
 * />
 *
 * @example
 * // Horizontal layout
 * <Card
 *   item={track}
 *   layout="horizontal"
 *   size="lg"
 *   showAlbum={false}
 * />
 */
export const Card: React.FC<CardProps> = ({
  item,
  size = 'md',
  layout = 'vertical',
  theme = 'light',
  hoverEffect = 'lift',
  showAlbum = true,
  shadow = true,
  expandableArtwork = false,
  zoomArtwork = false,
  platform = 'default',
  className = '',
  style = {},
  onClick,
  interactive = true,
  showPlayButton = false,
  onPlay,
}) => {
  // Determine artwork size based on card size and layout
  const getArtworkSize = (): AlbumArtworkSize => {
    if (layout === 'horizontal') {
      return size === 'sm' ? 'sm' : size === 'md' ? 'base' : 'md';
    } else {
      return 'auto'; // Full width for vertical layout
    }
  };

  // Handle click events
  const handleClick = (e: React.MouseEvent) => {
    if (interactive && onClick) {
      onClick();
    }
  };

  // Handle play button click
  const handlePlayClick = (e: React.MouseEvent) => {
    e.stopPropagation(); // Prevent card click
    if (onPlay) {
      onPlay();
    }
  };

  return (
    <CardContainer
      $size={size}
      $layout={layout}
      $theme={theme}
      $hoverEffect={hoverEffect}
      $shadow={shadow}
      $interactive={interactive}
      $platform={platform}
      className={`music-card ${className}`}
      style={style}
      onClick={handleClick}
      role={interactive ? 'button' : undefined}
      tabIndex={interactive ? 0 : undefined}
      onKeyDown={e => {
        if (interactive && onClick && (e.key === 'Enter' || e.key === ' ')) {
          e.preventDefault();
          onClick();
        }
      }}
    >
      <AlbumArtwork
        image={item.coverArt}
        name={item.title}
        size={getArtworkSize()}
        shadow={false} // We're already applying shadow to the card
        platform={platform}
        expandable={expandableArtwork}
        zoom={zoomArtwork}
        style={layout === 'vertical' ? { width: '100%' } : undefined}
      />

      <ContentContainer $layout={layout} $size={size}>
        <MetadataLabel
          text={item.title}
          truncate={true}
          maxLength={size === 'sm' ? 20 : size === 'md' ? 25 : 30}
          as="h3"
          style={{
            fontWeight: 600,
            fontSize: size === 'sm' ? '14px' : size === 'md' ? '16px' : '18px',
            margin: 0,
            lineHeight: 1.2,
            ...(platform === 'spotify' && {
              fontFamily: 'Circular, Helvetica, Arial, sans-serif',
              fontWeight: 700,
            }),
            ...(platform === 'apple' && {
              fontFamily: 'SF Pro Display, -apple-system, BlinkMacSystemFont, sans-serif',
              fontWeight: 600,
            }),
            ...(platform === 'tidal' && {
              fontFamily: 'Gotham, Helvetica, Arial, sans-serif',
              fontWeight: 500,
              letterSpacing: '0.5px',
            }),
          }}
        />

        <ArtistLabel
          artists={item.artist}
          truncate={true}
          maxLength={size === 'sm' ? 20 : size === 'md' ? 25 : 30}
          style={{
            fontSize: size === 'sm' ? '12px' : size === 'md' ? '14px' : '16px',
            color: 'var(--color-text-muted, #6b7280)',
            lineHeight: 1.2,
            ...(platform === 'spotify' && {
              fontFamily: 'Circular, Helvetica, Arial, sans-serif',
              color: 'rgba(255, 255, 255, 0.7)',
              fontSize: size === 'sm' ? '11px' : size === 'md' ? '13px' : '15px',
            }),
            ...(platform === 'apple' && {
              fontFamily: 'SF Pro Text, -apple-system, BlinkMacSystemFont, sans-serif',
              color: theme === 'dark' ? 'rgba(255, 255, 255, 0.6)' : 'rgba(0, 0, 0, 0.6)',
            }),
            ...(platform === 'tidal' && {
              fontFamily: 'Gotham, Helvetica, Arial, sans-serif',
              color: 'rgba(255, 255, 255, 0.7)',
              letterSpacing: '0.3px',
              textTransform: 'uppercase',
              fontSize: size === 'sm' ? '10px' : size === 'md' ? '11px' : '12px',
            }),
          }}
        />

        {showAlbum && item.album && (
          <MetadataLabel
            text={item.album}
            truncate={true}
            maxLength={size === 'sm' ? 20 : size === 'md' ? 25 : 30}
            style={{
              fontSize: size === 'sm' ? '11px' : size === 'md' ? '12px' : '14px',
              color: 'var(--color-text-muted, #6b7280)',
              fontStyle: 'italic',
              ...(platform === 'spotify' && {
                fontFamily: 'Circular, Helvetica, Arial, sans-serif',
                color: 'rgba(255, 255, 255, 0.6)',
                fontStyle: 'normal',
              }),
              ...(platform === 'apple' && {
                fontFamily: 'SF Pro Text, -apple-system, BlinkMacSystemFont, sans-serif',
                color: theme === 'dark' ? 'rgba(255, 255, 255, 0.5)' : 'rgba(0, 0, 0, 0.5)',
              }),
              ...(platform === 'tidal' && {
                fontFamily: 'Gotham, Helvetica, Arial, sans-serif',
                color: 'rgba(255, 255, 255, 0.6)',
                fontStyle: 'normal',
                letterSpacing: '0.3px',
              }),
            }}
          />
        )}
      </ContentContainer>

      {showPlayButton && interactive && (
        <PlayButtonOverlay
          $platform={platform}
          onClick={handlePlayClick}
          role="button"
          aria-label={`Play ${item.title}`}
        />
      )}
    </CardContainer>
  );
};

